Section HCWP.
  Context {HCEIL : HeapCeil}.

  Ltac dv_kill K := try (exfalso; try rewrite signed_small in K by lia; try rewrite wz_unsigned in K by lia; try rewrite b8_unsigned in K by lia; lia).
  Ltac tk K := if_cases K; zify_cond K; dv_kill K;
    try (exfalso; revert K; rewrite ?Z.shiftl_mul_pow2 by lia; rewrite ?Zmod_0_l; rewrite ?unsigned_lit by lia; cbn; lia);
